install -d -m 0755 /usr/share/nginx/html
printf 'Nginx on %s\n' "$NODE_NAME" > /usr/share/nginx/html/index.html
cat > /etc/nginx/conf.d/benchmark-6700.conf <<'ANTRIEB_NGINX'
server {
    listen 6700 default_server;
    listen [::]:6700 default_server;
    server_name _;
    root /usr/share/nginx/html;
    index index.html;
    location / {
        try_files $uri $uri/ =404;
    }
}
